import sys
from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def lcm_multiple(numbers):
    return reduce(lcm, numbers)

def solve():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    X = list(map(int, data[2:2 + K]))
    Q = int(data[2 + K])
    queries = []

    index = 2 + K
    for _ in range(Q):
        L = int(data[index])
        R = int(data[index + 1])
        queries.append((L, R))
        index += 2

    # Calculate the LCM of all jump values
    jump_lcm = lcm_multiple(X)

    # Calculate the number of times each index is incremented
    increment_count = [0] * N
    for jump in X:
        for i in range(jump):
            increment_count[i] += N // jump

    # Adjust for the overlap
    for jump in X:
        for i in range(jump):
            if (N - 1 - i) // jump + 1 > 1:
                increment_count[i] += (N - 1 - i) // jump - (N // jump - 1)

    # Calculate prefix sums
    prefix_sums = [0] * (N + 1)
    for i in range(N):
        prefix_sums[i + 1] = prefix_sums[i] + increment_count[i]

    # Answer the queries
    results = []
    for L, R in queries:
        results.append(prefix_sums[R + 1] - prefix_sums[L])

    # Print results
    for result in results:
        print(result)

